package dominoes

// Domino is a pair of dots on the two halves of a stone.
type Domino [2]int

// MakeChain tries to order the given dominoes so that adjacent halves match
// and the two open ends (first and last halves) match each other, forming a
// closed chain. It returns the chain and true on success, or nil and false
// if no such ordering exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	chain := make([]Domino, 0, len(input))
	if solve(input, chain) {
		return chain, true
	}
	return nil, false
}

// solve attempts to build a closed chain by appending unused dominoes to
// chain, trying both orientations of each remaining stone.
func solve(remaining []Domino, chain []Domino) bool {
	if len(remaining) == 0 {
		// Closed chain: the open end must match the start.
		return len(chain) == 0 || chain[0][0] == chain[len(chain)-1][1]
	}
	for i, d := range remaining {
		for _, orientation := range [2]Domino{d, {d[1], d[0]}} {
			if len(chain) > 0 && chain[len(chain)-1][1] != orientation[0] {
				continue
			}
			next := make([]Domino, len(chain), len(chain)+1)
			copy(next, chain)
			next = append(next, orientation)
			if solve(removeAt(remaining, i), next) {
				chain = next
				return true
			}
		}
	}
	return false
}

// removeAt returns a copy of d without the element at index i.
func removeAt(d []Domino, i int) []Domino {
	out := make([]Domino, 0, len(d)-1)
	out = append(out, d[:i]...)
	out = append(out, d[i+1:]...)
	return out
}

